            {
                string current = _spotifyModule.GetSnapshot().Playback.RepeatMode;
                string next = current?.ToLowerInvariant() switch
                {
                    "off" => "context",
                    "context" => "track",
                    _ => "off"
                };
                await _spotifyModule.SetRepeatAsync(next);
                await RefreshSpotifyAsync();
            });
