        RefreshStreamDeckAutomationRules();
        InstallStreamDeckButton.Click += async (_, _) =>
            await ExportStreamDeckProfileAsync();

        OpenStreamDeckFolderButton.Click += (_, _) =>
            OpenLocalDataFolder("StreamDeck");


    }

