    private async Task ApplyTwitchChatUiModeAsync()
    {
        bool web = _settings.Twitch.ChatUiMode == TwitchChatUiMode.EmbeddedWeb;

        DashboardTwitchChatList.Visibility = web ? Visibility.Collapsed : Visibility.Visible;
        DashboardTwitchWebChat.Visibility = web ? Visibility.Visible : Visibility.Collapsed;
        DashboardTwitchChatHeader.Visibility = web ? Visibility.Collapsed : Visibility.Visible;
        DashboardTwitchChatControls.Visibility = web ? Visibility.Collapsed : Visibility.Visible;
        DashboardTwitchChatHeaderRow.Height = web ? new GridLength(0) : GridLength.Auto;
        DashboardTwitchChatControlsRow.Height = web ? new GridLength(0) : GridLength.Auto;
        DashboardTwitchChatContentHost.Margin = web ? new Thickness(0) : new Thickness(0, 8, 0, 8);
        DashboardTwitchChatModule.Padding = web ? new Thickness(0) : new Thickness(10);

        ServicesTwitchChatList.Visibility = web ? Visibility.Collapsed : Visibility.Visible;
        ServicesTwitchWebChat.Visibility = web ? Visibility.Visible : Visibility.Collapsed;

        TwitchBuiltInChatPanel.Visibility = web ? Visibility.Collapsed : Visibility.Visible;
        TwitchWebChatSettingsHint.Visibility = web ? Visibility.Visible : Visibility.Collapsed;

        if (!web)
        {
            return;
        }

        await RefreshTwitchWebChatViewsAsync(forceReload: false);
    }

    private async Task RefreshTwitchWebChatViewsAsync(bool forceReload)
    {
        if (_settings.Twitch.ChatUiMode != TwitchChatUiMode.EmbeddedWeb)
        {
            return;
        }

        string? channel = ResolveTwitchChatChannel();
        if (string.IsNullOrWhiteSpace(channel))
        {
            return;
        }

        string url = TwitchWebViewProfile.BuildPopoutChatUrl(channel);
        if (!forceReload &&
            string.Equals(_lastTwitchWebChatUrl, url, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        try
        {
            await EnsureAndNavigateTwitchWebChatAsync(DashboardTwitchWebChat, url, forceReload);
            await EnsureAndNavigateTwitchWebChatAsync(ServicesTwitchWebChat, url, forceReload);
            _lastTwitchWebChatUrl = url;
        }
        catch (WebView2RuntimeNotFoundException)
        {
            AddDashboardNotification(
                "WebView2 Runtime fehlt. Bitte Evergreen Runtime installieren oder den Systembrowser nutzen.",
                "Warnung");
            MessageBoxResult result = MessageBox.Show(
                this,
                "Die Microsoft Edge WebView2 Runtime ist nicht installiert.\n\nInstaller jetzt im Browser öffnen?",
                "WebView2 Runtime fehlt",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning);
            if (result == MessageBoxResult.Yes)
            {
                OpenConfiguredTarget(TwitchWebViewProfile.RuntimeInstallerUrl, "WebView2 Runtime");
            }
        }
        catch (Exception ex)
        {
            AddDashboardNotification("Web-Chat konnte nicht geladen werden: " + ex.Message, "Warnung");
        }
    }

    private static async Task EnsureAndNavigateTwitchWebChatAsync(WebView2 webView, string url, bool forceReload = false)
    {
        await TwitchWebViewProfile.EnsureAsync(webView);
        if (!forceReload &&
            webView.Source?.AbsoluteUri is string current &&
            string.Equals(current, url, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        if (forceReload && webView.CoreWebView2 is not null)
        {
            webView.CoreWebView2.Navigate(url);
            return;
        }

        webView.Source = new Uri(url);
    }


    private async Task RefreshTwitchGoalsAsync()
    {
        if (!_twitchModule.GetSnapshot().Authenticated)
        {
            _currentActiveSubscriptionCount = 0;
            DashboardChatAlertsText.Text = "0";
            return;
        }

        try
        {
            Task<int> followerTask = _twitchModule.GetFollowerCountAsync();
            Task<int> subscriptionTask = _twitchModule.GetActiveSubscriptionCountAsync();

            await Task.WhenAll(followerTask, subscriptionTask);

            _currentFollowerCount = Math.Max(0, followerTask.Result);
            _currentActiveSubscriptionCount =
                Math.Max(0, subscriptionTask.Result);

            _settings.Twitch.FollowerGoal.Current =
                _currentFollowerCount;
            _settings.Twitch.SubGoal.Current =
                _currentActiveSubscriptionCount;

            FollowerGoalCurrentBox.Text =
                _currentFollowerCount.ToString();
            SubGoalCurrentBox.Text =
                _currentActiveSubscriptionCount.ToString();

            DashboardFollowerTotalText.Text =
                $"Gesamt: {_currentFollowerCount}";
            DashboardHeroFollowerText.Text = _currentFollowerCount.ToString();
            DashboardChatAlertsText.Text = _currentActiveSubscriptionCount.ToString();
            DashboardTwitchGoalsText.Text =
                $"Follower-Ziel: {_currentFollowerCount:0} / {_settings.Twitch.FollowerGoal.Target:0} · " +
                $"Sub-Ziel: {_currentActiveSubscriptionCount:0} / {_settings.Twitch.SubGoal.Target:0}";

            await _overlayModule.Service.UpdateAsync(data =>
            {
                data.Twitch.Followers = _currentFollowerCount;
                data.Twitch.FollowerGoalState.Current =
                    _currentFollowerCount;
                data.Twitch.FollowerGoalState.Target =
                    _settings.Twitch.FollowerGoal.Target;
                data.Twitch.FollowerGoalState.Title =
                    _settings.Twitch.FollowerGoal.Title;
                data.Twitch.FollowerGoalState.FontFace =
                    _settings.Twitch.FollowerGoal.FontFace;
                data.Twitch.FollowerGoalState.FontSize =
                    _settings.Twitch.FollowerGoal.FontSize;

                data.Twitch.SubGoalState.Current =
                    _currentActiveSubscriptionCount;
                data.Twitch.SubGoalState.Target =
                    _settings.Twitch.SubGoal.Target;
                data.Twitch.SubGoalState.Title =
                    _settings.Twitch.SubGoal.Title;
                data.Twitch.SubGoalState.FontFace =
                    _settings.Twitch.SubGoal.FontFace;
                data.Twitch.SubGoalState.FontSize =
                    _settings.Twitch.SubGoal.FontSize;
            });
        }
        catch (Exception exception)
        {
            _appLogger.Write(
                AppLogLevel.Warning,
                "Twitch",
                "Twitch-Ziele konnten nicht automatisch aktualisiert werden.",
                exception);
        }
    }

    private async Task RefreshTwitchFollowerCountAsync(
        bool initializeStreamBaseline = false)
    {
        if (!_twitchModule.GetSnapshot().Authenticated)
        {
            return;
        }

        try
        {
            int followerCount =
                await _twitchModule.GetFollowerCountAsync();

            _currentFollowerCount = Math.Max(0, followerCount);

            if (initializeStreamBaseline)
            {
                _streamFollowerBaseline = _currentFollowerCount;
                _twitchSessionChatMessages = 0;
                _twitchSessionEvents = 0;
                _twitchSessionUniqueChatters.Clear();
                _twitchSessionObservedAt = DateTimeOffset.Now;
                RefreshTwitchProfessionalUi();
            }

            int baseline = _streamFollowerBaseline > 0
                ? _streamFollowerBaseline
                : _currentFollowerCount;

            await _workflowModule.Service.SetFollowerCountsAsync(
                baseline,
                _currentFollowerCount);

            DashboardFollowerTotalText.Text =
                $"Gesamt: {_currentFollowerCount}";
            DashboardFollowersGainedText.Text =
                Math.Max(
                        0,
                        _currentFollowerCount - baseline)
                    .ToString();

            await _overlayModule.Service.UpdateAsync(data =>
            {
                data.Twitch.Followers = _currentFollowerCount;
            });
            await UpdateActiveOverlayJsonAsync(root =>
            {
                JsonObject twitch = root["twitch"] as JsonObject ?? [];
                twitch["followers"] = _currentFollowerCount;
                twitch["followerGoal"] = _settings.Twitch.FollowerGoal.Target;
                JsonObject goal = twitch["followerGoalState"] as JsonObject ?? [];
                goal["title"] = _settings.Twitch.FollowerGoal.Title;
                goal["current"] = _currentFollowerCount;
                goal["target"] = _settings.Twitch.FollowerGoal.Target;
                goal["fontFace"] = _settings.Twitch.FollowerGoal.FontFace;
                goal["fontSize"] = _settings.Twitch.FollowerGoal.FontSize;
                twitch["followerGoalState"] = goal;
                root["twitch"] = twitch;
            });
            DashboardTwitchGoalsText.Text =
                $"Follower-Ziel: {_currentFollowerCount:0} / {_settings.Twitch.FollowerGoal.Target:0} · " +
                $"Sub-Ziel: {_currentActiveSubscriptionCount:0} / {_settings.Twitch.SubGoal.Target:0}";
        }
        catch (Exception exception)
        {
            _appLogger.Write(
                AppLogLevel.Warning,
                "Twitch",
                "Followerzahl konnte nicht aktualisiert werden.",
                exception);
        }
    }

    private async Task RefreshLiveViewerSampleAsync()
    {
        if (_liveViewerSampleRunning)
        {
            return;
        }

        TwitchConnectionSnapshot twitchSnapshot = _twitchModule.GetSnapshot();
        if (!twitchSnapshot.Authenticated)
        {
            _twitchStreamStartedAt = null;
            _currentLiveViewerCount = 0;
            DashboardHeroViewerText.Text = "0";
            AddDashboardViewerTrendSample(0);
            RefreshTwitchProfessionalUi();
            ApplyTwitchUsersRefreshInterval();
            return;
        }

        // Helix' `login` parameter expects the canonical login, not the
        // user-facing display name (which may contain different casing or
        // localized characters).
        string channel = !string.IsNullOrWhiteSpace(twitchSnapshot.ChannelLogin)
            ? twitchSnapshot.ChannelLogin
            : twitchSnapshot.Login;

        if (string.IsNullOrWhiteSpace(channel))
        {
            return;
        }

        _liveViewerSampleRunning = true;

        try
        {
            TwitchRaidTargetStatus? status = await _twitchModule.GetRaidTargetStatusAsync(channel);

            if (status is null || !status.IsOnline)
            {
                _twitchStreamStartedAt = null;
                _currentLiveViewerCount = 0;
                DashboardHeroViewerText.Text = "0";
                AddDashboardViewerTrendSample(0);
                RefreshTwitchProfessionalUi();
                RefreshWorkflowUi(_workflowModule.Service.State);
                ApplyTwitchUsersRefreshInterval();
                return;
            }

            // Helix streams.started_at ist die Zuschauer-sichtbare Live-Dauer auf Twitch.
            // Lokale OBS-/Workflow-Zeiten dienen nur als Fallback, bis Twitch den Stream meldet.
            ApplyTwitchLiveStreamStartedAt(status.StartedAt);

            _currentLiveViewerCount = Math.Max(0, status.ViewerCount);
            ApplyTwitchUsersRefreshInterval();
            await _creatorIntelligence.RecordAsync("twitch.viewer.sample", new { viewers = _currentLiveViewerCount, scene = _servicesObsCurrentScene, category = status.GameName, title = status.StreamTitle });
            RefreshTwitchProfessionalUi(status);

            await _workflowModule.Service.AddViewerSampleAsync(
                _currentLiveViewerCount);

            RefreshWorkflowUi(_workflowModule.Service.State);

            await _overlayModule.Service.UpdateAsync(data =>
            {
                data.Stream.ViewerCount = _currentLiveViewerCount;
            });
            DateTimeOffset? liveStartedAt = ResolveLiveStreamStartedAt();
            await UpdateActiveOverlayJsonAsync(root =>
            {
                JsonObject stream = root["stream"] as JsonObject ?? [];
                stream["viewerCount"] = _currentLiveViewerCount;
                stream["isLive"] = true;
                stream["startedAt"] = liveStartedAt;
                stream["elapsedSeconds"] = liveStartedAt.HasValue
                    ? Math.Max(0, (long)(DateTimeOffset.Now - liveStartedAt.Value).TotalSeconds)
                    : 0;
                root["stream"] = stream;
            });
        }
        catch (Exception exception)
        {
            _appLogger.Write(
                AppLogLevel.Warning,
                "Twitch",
                "Aktuelle Zuschauerzahl konnte nicht aktualisiert werden.",
                exception);
        }
        finally
        {
            _liveViewerSampleRunning = false;
        }
    }

    private async Task RefreshRaidTargetStatusAsync(string channel)
    {
        if (string.IsNullOrWhiteSpace(channel))
        {
            _raidTargetIsOnline = false;
            SetRaidTargetStatusText("Kein Ziel ausgewählt");
            DashboardRaidAssistantText.Text = "Kein Raid-Ziel ausgewählt.";
            DashboardRaidLiveDurationText.Text = "Live-Dauer: -";
            ServicesTwitchRaidLiveDurationText.Text = "Live-Dauer: -";
            DashboardRaidProfileImage.Source = null;
            ServicesTwitchRaidProfileImage.Source = null;
            UpdateDashboardRaidActionButtons();
            return;
        }

        try
        {
            TwitchRaidTargetStatus? status = await _twitchModule.GetRaidTargetStatusAsync(channel.Trim());
            if (status is null)
            {
                _raidTargetIsOnline = false;
                SetRaidTargetStatusText($"{channel}: Kanal nicht gefunden");
                UpdateDashboardRaidActionButtons();
                return;
            }

            _raidTargetIsOnline = status.IsOnline;
            TimeSpan liveDuration = status.IsOnline && status.StartedAt is not null
                ? DateTimeOffset.Now - status.StartedAt.Value
                : TimeSpan.Zero;

            string text = status.IsOnline
                ? $"{status.DisplayName} ist ONLINE · {status.ViewerCount} Zuschauer · {status.GameName}" +
                  (string.IsNullOrWhiteSpace(status.StreamTitle) ? "" : $" · {status.StreamTitle}")
                : $"{status.DisplayName} ist OFFLINE";

            SetRaidTargetStatusText(text);
            DashboardRaidAssistantText.Text = text;
            DashboardRaidLiveDurationText.Text = status.IsOnline
                ? $"Live seit {FormatRaidLiveDuration(liveDuration)}"
                : "Live-Dauer: -";
            ServicesTwitchRaidLiveDurationText.Text = DashboardRaidLiveDurationText.Text;
            await LoadRaidProfileImageAsync(status.ProfileImageUrl);
            UpdateDashboardRaidActionButtons();
        }
        catch (Exception ex)
        {
            _raidTargetIsOnline = false;
            SetRaidTargetStatusText($"Status nicht verfügbar: {ex.Message}");
            UpdateDashboardRaidActionButtons();
        }
    }

    private async Task LoadRaidProfileImageAsync(string? imageUrl)
    {
        if (string.IsNullOrWhiteSpace(imageUrl))
        {
            DashboardRaidProfileImage.Source = null;
            ServicesTwitchRaidProfileImage.Source = null;
            return;
        }

        try
        {
            byte[] bytes = await RaidProfileHttpClient.GetByteArrayAsync(imageUrl);
            await Dispatcher.InvokeAsync(() =>
            {
                using var stream = new MemoryStream(bytes);
                var image = new System.Windows.Media.Imaging.BitmapImage();
                image.BeginInit();
                image.CacheOption = System.Windows.Media.Imaging.BitmapCacheOption.OnLoad;
                image.StreamSource = stream;
                image.EndInit();
                image.Freeze();
                DashboardRaidProfileImage.Source = image;
                ServicesTwitchRaidProfileImage.Source = image;
            });
        }
        catch
        {
            DashboardRaidProfileImage.Source = null;
            ServicesTwitchRaidProfileImage.Source = null;
        }
    }

    private static string FormatRaidLiveDuration(TimeSpan duration)
    {
        if (duration.TotalHours >= 1)
        {
            return $"{(int)duration.TotalHours}:{duration.Minutes:00} Std.";
        }

        return $"{Math.Max(0, duration.Minutes)} Min.";
    }

    private void SetRaidTargetStatusText(string text)
    {
        DashboardRaidTargetStatusText.Text = text;
        ServicesTwitchRaidTargetStatusText.Text = text;
        DashboardStreamEndTargetText.Text = text;
        _activeStreamEndDialog?.SetRaidTargetStatus(text);
    }

    private void OpenSelectedRaidChannel()
    {
        string channel = DashboardRaidChannelBox.SelectedItem as string
                      ?? ServicesTwitchRaidTargetBox.SelectedItem as string
                      ?? _settings.Twitch.SelectedRaidChannel;

        if (string.IsNullOrWhiteSpace(channel))
        {
            MessageBox.Show("Bitte zuerst ein Raid-Ziel auswählen.", "Twitch");
            return;
        }

        string url = "https://www.twitch.tv/" + Uri.EscapeDataString(channel.Trim().TrimStart('@'));
        Process.Start(new ProcessStartInfo(url) { UseShellExecute = true });
    }

    private void RefreshRaidChannelSelectors()
    {
        var channels = _settings.Twitch.RaidChannels
            .Select(channel => channel.Trim().TrimStart('@'))
            .Where(channel => !string.IsNullOrWhiteSpace(channel))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        _settings.Twitch.RaidChannels = channels;
        ServicesTwitchRaidChannelsBox.Text = string.Join(Environment.NewLine, channels);
        ServicesTwitchRaidChannelsList.ItemsSource = channels;
        DashboardRaidChannelBox.ItemsSource = channels;
        ServicesTwitchRaidTargetBox.ItemsSource = channels;
        DashboardRaidChannelBox.SelectedItem = channels.FirstOrDefault(channel => string.Equals(channel, _settings.Twitch.SelectedRaidChannel, StringComparison.OrdinalIgnoreCase));
        ServicesTwitchRaidTargetBox.SelectedItem = DashboardRaidChannelBox.SelectedItem;
    }

    private void RememberRaidChannel(string channel)
    {
        channel = channel.Trim().TrimStart('@');
        if (string.IsNullOrWhiteSpace(channel))
        {
            return;
        }

        _settings.Twitch.RaidChannels.RemoveAll(item =>
            string.Equals(item, channel, StringComparison.OrdinalIgnoreCase));
        _settings.Twitch.RaidChannels.Insert(0, channel);
        if (_settings.Twitch.RaidChannels.Count > 40)
        {
            _settings.Twitch.RaidChannels.RemoveRange(40, _settings.Twitch.RaidChannels.Count - 40);
        }

        _settings.Twitch.SelectedRaidChannel = channel;
        RefreshRaidChannelSelectors();
    }

    private async Task<IReadOnlyList<TwitchChannelSuggestion>> SuggestRaidTargetsAsync(
        string query,
        CancellationToken cancellationToken)
    {
        query = query.Trim().TrimStart('@');

        var recentLogins = _settings.Twitch.RaidChannels
            .Select(channel => channel.Trim().TrimStart('@'))
            .Where(channel => !string.IsNullOrWhiteSpace(channel))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Where(channel => MatchesRaidQuery(channel, channel, query))
            .ToList();

        IReadOnlyList<TwitchChannelSuggestion> followed = [];
        IReadOnlyList<TwitchChannelSuggestion> followedLive = [];
        IReadOnlyList<TwitchChannelSuggestion> searched = [];
        var liveByLogin = new Dictionary<string, TwitchChannelSuggestion>(StringComparer.OrdinalIgnoreCase);

        try
        {
            followed = await GetFollowedRaidTargetsCachedAsync(cancellationToken);
        }
        catch
        {
            // Scope fehlt oder Twitch offline – lokale Vorschläge reichen.
        }

        try
        {
            followedLive = await GetFollowedLiveRaidTargetsCachedAsync(cancellationToken);
        }
        catch
        {
            // Optional
        }

        if (query.Length >= 2)
        {
            try
            {
                searched = await _twitchModule.SearchChannelsAsync(query, cancellationToken);
            }
            catch (OperationCanceledException)
            {
                throw;
            }
            catch
            {
                // Suche optional
            }
        }

        try
        {
            var loginsToCheck = recentLogins
                .Concat(followed
                    .Where(item => MatchesRaidQuery(item.Login, item.DisplayName, query))
                    .Select(item => item.Login)
                    .Take(80))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (loginsToCheck.Count > 0)
            {
                foreach (KeyValuePair<string, TwitchChannelSuggestion> pair in await _twitchModule.GetLiveChannelsByLoginsAsync(loginsToCheck, cancellationToken))
                {
                    liveByLogin[pair.Key] = pair.Value;
                }
            }
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch
        {
            // Live-Status optional
        }

        foreach (TwitchChannelSuggestion? live in followedLive.Concat(searched.Where(item => item.IsLive)))
        {
            liveByLogin.TryAdd(live.Login, live with { IsLive = true, SourceLabel = "Live" });
        }

        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var results = new List<TwitchChannelSuggestion>(25);

        // 1) Bereits geraidet – ganz oben; darin Live vor Offline
        var recentSuggestions = recentLogins
            .Select(login =>
            {
                bool isLive = liveByLogin.TryGetValue(login, out TwitchChannelSuggestion? liveInfo);
                string display = isLive ? liveInfo!.DisplayName : login;
                return new TwitchChannelSuggestion(login, display, isLive, "Zuletzt");
            })
            .OrderByDescending(item => item.IsLive)
            .ToList();

        foreach (TwitchChannelSuggestion? item in recentSuggestions)
        {
            if (!seen.Add(item.Login))
            {
                continue;
            }

            results.Add(item);
        }

        // 2) Weitere Live-Kanäle (Follows + Suche)
        foreach (TwitchChannelSuggestion? item in followedLive
                     .Concat(searched.Where(x => x.IsLive))
                     .Concat(liveByLogin.Values)
                     .Where(item => MatchesRaidQuery(item.Login, item.DisplayName, query)))
        {
            if (!seen.Add(item.Login))
            {
                continue;
            }

            results.Add(item with { IsLive = true, SourceLabel = "Live" });
            if (results.Count >= 25)
            {
                return results;
            }
        }

        // 3) Offline: gefolgte, dann Suche
        foreach (TwitchChannelSuggestion? item in followed
                     .Where(item => MatchesRaidQuery(item.Login, item.DisplayName, query))
                     .Concat(searched.Where(item => !item.IsLive)))
        {
            if (!seen.Add(item.Login))
            {
                continue;
            }

            results.Add(item with { IsLive = false });
            if (results.Count >= 25)
            {
                break;
            }
        }

        return results;
    }

    private async Task<IReadOnlyList<TwitchChannelSuggestion>> GetFollowedRaidTargetsCachedAsync(
        CancellationToken cancellationToken)
    {
        if (_followedRaidTargetCache is not null &&
            DateTimeOffset.UtcNow - _followedRaidTargetCacheAt < TimeSpan.FromMinutes(10))
        {
            return _followedRaidTargetCache;
        }

        IReadOnlyList<TwitchChannelSuggestion> followed = await _twitchModule.GetFollowedChannelsAsync(cancellationToken);
        _followedRaidTargetCache = followed;
        _followedRaidTargetCacheAt = DateTimeOffset.UtcNow;
        return followed;
    }

    private async Task<IReadOnlyList<TwitchChannelSuggestion>> GetFollowedLiveRaidTargetsCachedAsync(
        CancellationToken cancellationToken)
    {
        if (_followedLiveRaidTargetCache is not null &&
            DateTimeOffset.UtcNow - _followedLiveRaidTargetCacheAt < TimeSpan.FromMinutes(2))
        {
            return _followedLiveRaidTargetCache;
        }

        IReadOnlyList<TwitchChannelSuggestion> live = await _twitchModule.GetFollowedLiveStreamsAsync(cancellationToken);
        _followedLiveRaidTargetCache = live;
        _followedLiveRaidTargetCacheAt = DateTimeOffset.UtcNow;
        return live;
    }

    private static bool MatchesRaidQuery(string login, string displayName, string query)
    {
        if (string.IsNullOrWhiteSpace(query))
        {
            return true;
        }

        return login.Contains(query, StringComparison.OrdinalIgnoreCase) ||
               displayName.Contains(query, StringComparison.OrdinalIgnoreCase);
    }

    private void OnStreamEndRaidTargetChanged(string channel)
    {
        _raidTargetSuggestStatusCts?.Cancel();
        _raidTargetSuggestStatusCts?.Dispose();
        _raidTargetSuggestStatusCts = new CancellationTokenSource();
        CancellationToken token = _raidTargetSuggestStatusCts.Token;
        _ = Dispatcher.InvokeAsync(async () =>
        {
            try
            {
                await Task.Delay(350, token);
                if (token.IsCancellationRequested)
                {
                    return;
                }

                await RefreshRaidTargetStatusAsync(channel);
            }
            catch (OperationCanceledException)
            {
            }
        });
    }

    private void UpdateDashboardRaidControlsVisibility()
    {
        Visibility visibility = _settings.Twitch.RaidOnStreamEnd
            ? Visibility.Visible
            : Visibility.Collapsed;
        DashboardRaidSelectionPanel.Visibility = visibility;
        DashboardOpenRaidChannelButton.Visibility = visibility;
        UpdateDashboardStreamEndModuleVisibility();
        UpdateDashboardRaidActionButtons();
    }

    private void UpdateDashboardStreamEndModuleVisibility()
    {
        DashboardStreamEndModule.Visibility = Visibility.Collapsed;
        DashboardPlanStreamEndButton.Visibility = _plannedStreamEndActive ? Visibility.Collapsed : Visibility.Visible;
        DashboardCancelPlannedStreamEndButton.Visibility = _plannedStreamEndActive ? Visibility.Visible : Visibility.Collapsed;
        DashboardSkipRaidAndStopButton.Visibility = _awaitingManualRaid || _streamEndFlowActive
            ? Visibility.Visible
            : Visibility.Collapsed;

        _activeStreamEndDialog?.ShowRaidActions(_awaitingManualRaid && !_raidCountdownActive);
    }

    private void UpdateDashboardRaidActionButtons()
    {
        bool hasTarget = !string.IsNullOrWhiteSpace(_settings.Twitch.SelectedRaidChannel);
        bool canSkipCountdown = _raidCountdownActive;
        bool raidReady = hasTarget && _raidTargetIsOnline && !_raidCountdownActive
            && (_awaitingManualRaid || _streamEndFlowActive);
        bool showJetztRaiden = raidReady || canSkipCountdown;
        DashboardStartRaidButton.IsEnabled = showJetztRaiden;
        DashboardStartRaidButton.Visibility = showJetztRaiden ? Visibility.Visible : Visibility.Collapsed;
        DashboardCancelRaidButton.IsEnabled = _raidCountdownActive;

        _activeStreamEndDialog?.SetRaidReady(showJetztRaiden);
        _activeStreamEndDialog?.SetCancelRaidEnabled(_raidCountdownActive);
        if (_awaitingManualRaid && !_raidCountdownActive)
        {
            _activeStreamEndDialog?.ShowRaidActions(true);
        }
    }

    private async Task AddRaidChannelAsync()
    {
        string channel = ServicesTwitchNewRaidChannelBox.Text.Trim().TrimStart('@');
        if (string.IsNullOrWhiteSpace(channel))
        {
            return;
        }

        RememberRaidChannel(channel);
        ServicesTwitchNewRaidChannelBox.Clear();
        await _settingsStore.SaveAsync(_settings);
        await RefreshRaidTargetStatusAsync(channel);
    }

    private async Task RemoveSelectedRaidChannelAsync()
    {
        if (ServicesTwitchRaidChannelsList.SelectedItem is not string channel)
        {
            return;
        }

        _settings.Twitch.RaidChannels.RemoveAll(item => string.Equals(item, channel, StringComparison.OrdinalIgnoreCase));
        if (string.Equals(_settings.Twitch.SelectedRaidChannel, channel, StringComparison.OrdinalIgnoreCase))
        {
            _settings.Twitch.SelectedRaidChannel = _settings.Twitch.RaidChannels.FirstOrDefault() ?? "";
        }

        RefreshRaidChannelSelectors();
        await _settingsStore.SaveAsync(_settings);
        await RefreshRaidTargetStatusAsync(_settings.Twitch.SelectedRaidChannel);
    }

    private void ApplySpotifyAutomationFieldsToSettings()
    {
        _settings.Workflow.AutoStartSpotifyPlaylist = ServicesSpotifyAutoStartOnStreamBox.IsChecked == true;
        _settings.Workflow.AutoPlayEndMusic = ServicesSpotifyEndMusicBox.IsChecked == true;
        _settings.Workflow.PauseSpotifyOnStreamEnd = ServicesSpotifyPauseOnStreamEndBox.IsChecked == true;
        _settings.Spotify.SetVolumeOnLiveTransition = ServicesSpotifySetLiveVolumeBox.IsChecked == true;
        _settings.Spotify.LiveVolumePercent = int.TryParse(ServicesSpotifyLiveVolumeBox.Text, out int liveVolume)
            ? Math.Clamp(liveVolume, 0, 100)
            : 75;
        _settings.Spotify.MuteDuringAlerts = ServicesSpotifyMuteDuringAlertsBox.IsChecked == true;
        _settings.Spotify.AlertDuckingMode = _settings.Spotify.MuteDuringAlerts ? "Reduce" : "None";
        _settings.Spotify.AlertMuteVolumePercent = int.TryParse(ServicesSpotifyAlertVolumeBox.Text, out int alertVolume)
            ? Math.Clamp(alertVolume, 0, 100)
            : 50;
        _settings.Spotify.AlertFadeOutMilliseconds = int.TryParse(ServicesSpotifyAlertFadeOutMsBox.Text, out int fadeOutMs)
            ? Math.Clamp(fadeOutMs, 0, 10000)
            : 500;
        _settings.Spotify.AlertFadeInMilliseconds = int.TryParse(ServicesSpotifyAlertFadeInMsBox.Text, out int fadeInMs)
            ? Math.Clamp(fadeInMs, 0, 10000)
            : 500;
        _settings.Spotify.ShuffleSelectedPlaylist = ServicesSpotifyShufflePlaylistBox.IsChecked == true;
        if (ServicesSpotifyStartPlaylistBox.SelectedItem is SpotifyPlaylist playlist)
        {
            _settings.Spotify.StartPlaylistUri = playlist.Uri;
        }
    }

    private async Task SaveSpotifyAutomationSettingsAsync()
    {
        if (_loadingSettingsIntoUi)
        {
            return;
        }

        ApplySpotifyAutomationFieldsToSettings();
        await _settingsStore.SaveAsync(_settings);
        ServicesSpotifyAutomationStatusText.Text = "Spotify-Automatik gespeichert.";
    }

    private void ApplyTwitchEndFieldsToSettings()
    {
        _settings.Twitch.RaidOnStreamEnd = ServicesTwitchRaidEnabledBox.IsChecked == true;
        _settings.Twitch.RaidCountdownSeconds = int.TryParse(ServicesTwitchRaidCountdownSecondsBox.Text, out int raidSeconds)
            ? Math.Clamp(raidSeconds, 5, 300)
            : 90;
        _settings.Twitch.RaidStartTimeoutSeconds = int.TryParse(
                ServicesTwitchRaidStartTimeoutSecondsBox.Text,
                out int raidStartTimeout)
            ? RaidStartPolicy.ClampTimeoutSeconds(raidStartTimeout)
            : RaidStartPolicy.DefaultTimeoutSeconds;
        _settings.Twitch.StopStreamAfterRaid = ServicesTwitchStopStreamAfterRaidBox.IsChecked != false;
        _settings.Twitch.StopSpotifyAfterRaid = ServicesTwitchStopSpotifyAfterRaidBox.IsChecked != false;
        _settings.Twitch.RaidChannels = [.. ServicesTwitchRaidChannelsBox.Text
            .Split(['\r', '\n', ',', ';'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Distinct(StringComparer.OrdinalIgnoreCase)];
        if (ServicesTwitchRaidTargetBox.SelectedItem is string raidTarget)
        {
            _settings.Twitch.SelectedRaidChannel = raidTarget;
        }
        else if (!_settings.Twitch.RaidChannels.Contains(_settings.Twitch.SelectedRaidChannel, StringComparer.OrdinalIgnoreCase))
        {
            _settings.Twitch.SelectedRaidChannel = _settings.Twitch.RaidChannels.FirstOrDefault() ?? "";
        }
        _settings.Workflow.EndSceneSeconds = int.TryParse(ServicesTwitchEndSceneSecondsBox.Text, out int seconds) ? Math.Max(0, seconds) : 60;
        _settings.Twitch.EndSceneDurationSeconds = _settings.Workflow.EndSceneSeconds;

        if (double.TryParse(ServicesTwitchEndFollowerGoalTargetBox.Text.Replace(',', '.'),
                System.Globalization.NumberStyles.Float,
                System.Globalization.CultureInfo.InvariantCulture,
                out double followerTarget))
        {
            _settings.Twitch.FollowerGoal.Target = Math.Max(1, followerTarget);
        }

        // Beide Eingabefelder bearbeiten denselben Zielwert.
        FollowerGoalTargetBox.Text = _settings.Twitch.FollowerGoal.Target.ToString("0");
        ServicesTwitchEndFollowerGoalTargetBox.Text = _settings.Twitch.FollowerGoal.Target.ToString("0");
    }

    private async Task RefreshTwitchRewardsAsync()
    {
        try
        {
            IReadOnlyList<TwitchChannelPointReward> rewards = await _twitchModule.GetCustomRewardsAsync();
            ServicesRewardsList.ItemsSource = rewards.Select(reward => $"{reward.Title} · {reward.Cost:N0} Punkte").ToList();
        }
        catch (Exception exception)
        {
            ServicesRewardsList.ItemsSource = new[] { "Fehler: " + exception.Message };
        }
    }

    private async Task CreateTwitchRewardAsync()
    {
        try
        {
            string title = ServicesRewardTitleBox.Text.Trim();
            if (string.IsNullOrWhiteSpace(title))
            {
                throw new InvalidOperationException("Bitte einen Titel für die Belohnung eingeben.");
            }

            if (!int.TryParse(ServicesRewardCostBox.Text, out int cost) || cost < 1)
            {
                throw new InvalidOperationException("Die Punktekosten müssen mindestens 1 betragen.");
            }

            TwitchChannelPointReward reward = await _twitchModule.CreateCustomRewardAsync(title, cost, ServicesRewardPromptBox.Text);
            ServicesRewardTitleBox.Clear();
            ServicesRewardPromptBox.Clear();
            await RefreshTwitchRewardsAsync();
            ServicesRewardsList.ToolTip = $"Belohnung '{reward.Title}' wurde erstellt.";
        }
        catch (Exception exception)
        {
            MessageBox.Show(exception.Message, "Twitch Channel Points", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private async Task CreateTwitchPollAsync()
    {
        try
        {
            var choices = ServicesPollChoicesBox.Text.Split(['\r', '\n'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
            if (string.IsNullOrWhiteSpace(ServicesPollTitleBox.Text))
            {
                throw new InvalidOperationException("Bitte eine Umfragefrage eingeben.");
            }

            if (choices.Count < 2 || choices.Count > 5)
            {
                throw new InvalidOperationException("Eine Umfrage benötigt zwei bis fünf Antworten.");
            }

            int duration = int.TryParse(ServicesPollDurationBox.Text, out int parsed) ? Math.Clamp(parsed, 15, 1800) : 60;
            TwitchPoll poll = await _twitchModule.CreatePollAsync(ServicesPollTitleBox.Text, choices, duration);
            _activeTwitchPollId = poll.Id;
            ServicesPollStatusText.Text = $"Aktiv: {poll.Title} · {duration} Sekunden";
        }
        catch (Exception exception)
        {
            MessageBox.Show(exception.Message, "Twitch-Umfrage", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private async Task EndTwitchPollAsync(string status)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(_activeTwitchPollId))
            {
                throw new InvalidOperationException("Es ist keine in dieser Sitzung gestartete Umfrage vorhanden.");
            }

            TwitchPoll poll = await _twitchModule.EndPollAsync(_activeTwitchPollId, status);
            ServicesPollStatusText.Text = $"{poll.Status}: {poll.Title}";
            if (!status.Equals("TERMINATED", StringComparison.OrdinalIgnoreCase))
            {
                _activeTwitchPollId = null;
            }
        }
        catch (Exception ex) { ShowError("Umfrage konnte nicht aktualisiert werden", ex); }
    }

    private async Task EndTwitchPredictionAsync(string status)
    {
        try
        {
            if (_activeTwitchPrediction is null)
            {
                throw new InvalidOperationException("Es ist keine in dieser Sitzung gestartete Vorhersage vorhanden.");
            }

            _activeTwitchPrediction = await _twitchModule.EndPredictionAsync(_activeTwitchPrediction.Id, status, null);
            ServicesPredictionWinnerBox.ItemsSource = _activeTwitchPrediction.Outcomes;
            ServicesPredictionStatusText.Text = $"{_activeTwitchPrediction.Status}: {_activeTwitchPrediction.Title}";
        }
        catch (Exception ex) { ShowError("Vorhersage konnte nicht aktualisiert werden", ex); }
    }

    private async Task ResolveTwitchPredictionAsync()
    {
        try
        {
            if (_activeTwitchPrediction is null)
            {
                throw new InvalidOperationException("Es ist keine in dieser Sitzung gestartete Vorhersage vorhanden.");
            }

            if (ServicesPredictionWinnerBox.SelectedItem is not TwitchPredictionOutcome winner)
            {
                throw new InvalidOperationException("Bitte das Gewinnergebnis auswählen.");
            }

            _activeTwitchPrediction = await _twitchModule.EndPredictionAsync(_activeTwitchPrediction.Id, "RESOLVED", winner.Id);
            ServicesPredictionStatusText.Text = $"Aufgelöst: {winner.Title}";
        }
        catch (Exception ex) { ShowError("Vorhersage konnte nicht aufgelöst werden", ex); }
    }

    private async Task RefreshTwitchRedemptionsAsync()
    {
        try
        {
            if (ServicesRewardsList.SelectedItem is not TwitchChannelPointReward reward)
            {
                throw new InvalidOperationException("Bitte zuerst eine Channel-Point-Belohnung auswählen.");
            }

            IReadOnlyList<TwitchRewardRedemption> redemptions = await _twitchModule.GetRewardRedemptionsAsync(reward.Id);
            _twitchRedemptionItems.Clear();
            foreach (TwitchRewardRedemption redemption in redemptions)
            {
                _twitchRedemptionItems.Add(new TwitchRewardRedemptionItem(redemption));
            }
        }
        catch (Exception ex) { ShowError("Einlösungen konnten nicht geladen werden", ex); }
    }

    private async Task UpdateSelectedTwitchRedemptionAsync(string status)
    {
        try
        {
            if (ServicesRedemptionsList.SelectedItem is not TwitchRewardRedemptionItem selected)
            {
                throw new InvalidOperationException("Bitte eine offene Einlösung auswählen.");
            }

            await _twitchModule.UpdateRewardRedemptionStatusAsync(selected.Redemption.RewardId, selected.Redemption.Id, status);
            _twitchRedemptionItems.Remove(selected);
        }
        catch (Exception ex) { ShowError("Einlösung konnte nicht aktualisiert werden", ex); }
    }

    private async Task CreateTwitchPredictionAsync()
    {
        try
        {
            var outcomes = ServicesPredictionOutcomesBox.Text.Split(['\r', '\n'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
            if (string.IsNullOrWhiteSpace(ServicesPredictionTitleBox.Text))
            {
                throw new InvalidOperationException("Bitte eine Vorhersagefrage eingeben.");
            }

            if (outcomes.Count < 2 || outcomes.Count > 10)
            {
                throw new InvalidOperationException("Eine Vorhersage benötigt zwei bis zehn Ergebnisse.");
            }

            int window = int.TryParse(ServicesPredictionWindowBox.Text, out int parsed) ? Math.Clamp(parsed, 30, 1800) : 120;
            TwitchPrediction prediction = await _twitchModule.CreatePredictionAsync(ServicesPredictionTitleBox.Text, outcomes, window);
            _activeTwitchPrediction = prediction;
            ServicesPredictionWinnerBox.ItemsSource = prediction.Outcomes;
            ServicesPredictionStatusText.Text = $"Aktiv: {prediction.Title} · {window} Sekunden";
        }
        catch (Exception exception)
        {
            MessageBox.Show(exception.Message, "Twitch-Vorhersage", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

