    private static IReadOnlyDictionary<string, string>
        CreateAlertTestVariables(string type)
    {
        var values = new Dictionary<string, string>(
            StringComparer.OrdinalIgnoreCase);

        switch (type)
        {
            case "Raid":
                values["viewers"] = "25";
                break;

            case "Cheer":
                values["bits"] = "500";
                break;

            case "GiftSub":
                values["count"] = "5";
                break;

            case "ReSub":
                values["months"] = "12";
                break;
        }

        return values;
    }

