        ServicesSpotifyInactiveBanner.Visibility = isSpotify
            ? Visibility.Collapsed
            : Visibility.Visible;
        ServicesSpotifyButton.Content = isSpotify ? "●   Spotify" : "●   Spotify (inaktiv)";
        MusicPlayerSubtitleText.Text = "Aktiver Provider: " + displayName;
        MusicPlayerYouTubePanel.Visibility = isSpotify
            ? Visibility.Collapsed
            : Visibility.Visible;
        MusicPlayerSpotifyHintPanel.Visibility = isSpotify
            ? Visibility.Visible
            : Visibility.Collapsed;
        MusicPlayerVolumePanel.Visibility = isSpotify
            ? Visibility.Visible
            : Visibility.Collapsed;
        MusicPlayerProgressBar.IsEnabled = isSpotify;
        // YouTube Music liefert praktisch kein Album – Zeile ausblenden.
        Visibility albumVisibility = isSpotify ? Visibility.Visible : Visibility.Collapsed;
        DashboardTopMusicAlbumText.Visibility = albumVisibility;
        MusicPlayerAlbumText.Visibility = albumVisibility;
    }

    private async Task ExecuteMusicCommandAsync(Func<Task> action)
    {
        try
        {
            await action();
            await Task.Delay(350);
            if (IsSpotifyMusicProvider() && _spotifyModule.GetSnapshot().Authenticated)
            {
                await _spotifyModule.RefreshPlaybackAsync();
            }

            await RefreshMusicPlayerUiAsync();
            if (IsSpotifyMusicProvider())
            {
                RefreshSpotifyUi();
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message, "Music Player", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private bool _updatingMusicPlayerUi;
    private System.Windows.Point _musicBookmarkletDragStart;
    private bool _musicBookmarkletDragPending;

    private void UpdateMusicTitleMarquees()
    {
        UpdateTextMarquee(
            DashboardTopMusicTitleText,
            DashboardTopMusicTitleViewport,
            DashboardTopMusicTitleTranslate);
    }

    private static void UpdateTextMarquee(
        TextBlock textBlock,
        FrameworkElement viewport,
        TranslateTransform translate)
    {
        translate.BeginAnimation(TranslateTransform.XProperty, null);
        translate.X = 0;

        if (viewport.ActualWidth <= 0 || string.IsNullOrWhiteSpace(textBlock.Text))
        {
            return;
        }

        textBlock.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
        double overflow = textBlock.DesiredSize.Width - viewport.ActualWidth;
        if (overflow <= 2)
        {
            return;
        }

        double pixelsPerSecond = 28.0;
        double scrollSeconds = Math.Max(3.0, overflow / pixelsPerSecond);
        var animation = new DoubleAnimation
        {
            From = 0,
            To = -overflow,
            Duration = TimeSpan.FromSeconds(scrollSeconds),
            AutoReverse = true,
            RepeatBehavior = RepeatBehavior.Forever,
            BeginTime = TimeSpan.FromSeconds(1.25),
            EasingFunction = new SineEase { EasingMode = EasingMode.EaseInOut }
        };

        translate.BeginAnimation(TranslateTransform.XProperty, animation);
    }

    private void MusicPlayerBookmarkletDragChip_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        _musicBookmarkletDragStart = e.GetPosition(null);
        _musicBookmarkletDragPending = true;
    }

    private async void MusicPlayerBookmarkletDragChip_PreviewMouseMove(object sender, MouseEventArgs e)
    {
        if (!_musicBookmarkletDragPending || e.LeftButton != MouseButtonState.Pressed)
        {
            return;
        }

        Point position = e.GetPosition(null);
        if (Math.Abs(position.X - _musicBookmarkletDragStart.X) < SystemParameters.MinimumHorizontalDragDistance &&
            Math.Abs(position.Y - _musicBookmarkletDragStart.Y) < SystemParameters.MinimumVerticalDragDistance)
        {
            return;
        }

        _musicBookmarkletDragPending = false;
        try
        {
            if (!_youTubeMusicModule.IsBridgeRunning)
            {
                await _musicPlayerRouter.ConnectActiveAsync();
                await RefreshMusicPlayerUiAsync();
            }

            string bookmarklet = await _youTubeMusicModule.GetBookmarkletAsync();
            string title = _youTubeMusicModule.GetBookmarkletDisplayName();
            MusicPlayerBookmarkletDragLabel.Text = title;
            StartYouTubeMusicBookmarkletDrag(bookmarklet, title);
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                "Bookmarklet-Drag nicht möglich: " + ex.Message +
                "\n\nBitte zuerst verbinden und ggf. „Install-Seite öffnen“ nutzen.",
                "YouTube Music",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
        }
    }

    private static void StartYouTubeMusicBookmarkletDrag(string bookmarklet, string title)
    {
        var data = new DataObject();
        data.SetData(DataFormats.UnicodeText, bookmarklet);
        data.SetData(DataFormats.Text, bookmarklet);
        data.SetData("text/uri-list", bookmarklet + "\r\n");
        data.SetData("text/x-moz-url", bookmarklet + "\n" + title);

        // HTML-Format, damit Browser den Link inkl. Titel besser als Lesezeichen übernehmen.
        string href = System.Net.WebUtility.HtmlEncode(bookmarklet);
        string label = System.Net.WebUtility.HtmlEncode(title);
        string fragment = $"<a href=\"{href}\">{label}</a>";
        _ =
            "Version:0.9\r\n" +
            "StartHTML:00000097\r\n" +
            "EndHTML:00000100\r\n" +
            "StartFragment:00000097\r\n" +
            "EndFragment:00000100\r\n" +
            fragment;
        // Korrekte Offsets für das CF_HTML-Format berechnen.
        const string prefixTemplate =
            "Version:0.9\r\nStartHTML:{0:D8}\r\nEndHTML:{1:D8}\r\nStartFragment:{2:D8}\r\nEndFragment:{3:D8}\r\n";
        int headerLength = string.Format(
            System.Globalization.CultureInfo.InvariantCulture,
            prefixTemplate,
            0, 0, 0, 0).Length;
        int startHtml = headerLength;
        int startFragment = headerLength;
        int endFragment = startFragment + Encoding.UTF8.GetByteCount(fragment);
        int endHtml = endFragment;
        string? html = string.Format(
                  System.Globalization.CultureInfo.InvariantCulture,
                  prefixTemplate,
                  startHtml,
                  endHtml,
                  startFragment,
                  endFragment)
              + fragment;
        data.SetData(DataFormats.Html, html);

        DragDrop.DoDragDrop(
            Application.Current.MainWindow ?? throw new InvalidOperationException("MainWindow fehlt."),
            data,
            DragDropEffects.Copy);
    }

    private async Task OpenYouTubeMusicBookmarkletInstallPageAsync()
    {
